<!DOCTYPE html>
<html>
<head>
  <title>Personal Expense Tracker</title>
  <style>
    body { font-family: sans-serif; }
    #container { display: flex; }
    #form { width: 30%; padding: 20px; border: 1px solid #ccc; margin: 0 20px; }
    #list { width: 70%; padding: 20px; border: 1px solid #ccc; overflow-y: auto; }
    .expense { display: flex; align-items: center; justify-content: space-between; padding: 5px 0; }
    .cat-total { margin-bottom: 5px; }
  </style>
</head>
<body>

  <h1>Personal Expense Tracker</h1>

  <div id="container">
    <div id="form">
      <label for="#amount">Amount:</label>
      <input type="number" id="amount"><br><br>

      <label for="#category">Category:</label>
      <select id="category">
        <option value="groceries">Groceries</option>
        <option value="transport">Transport</option>
        <option value="bills">Bills</option>
        <option value="fun">Fun</option>
      </select><br><br>

      <label for="#date">Date:</label>
      <input type="date" id="date"><br><br>

      <label for="#note">Note (optional):</label>
      <textarea id="note"></textarea><br><br>

      <button id="add-expense">Add Expense</button>
      <div id="form-error"></div>
    </div>

    <div id="list">
      <!-- Expenses will be listed here -->
      <h2>Expenses</h2>
      <p id="total">0.00</p>
      <ul>
        <!-- Example expense - remove for final solution -->
      </ul>
      <div class="cat-total" data-cat="groceries"></div>
      <div class="cat-total" data-cat="transport"></div>
      <div class="cat-total" data-cat="bills"></div>
      <div class="cat-total" data-cat="fun"></div>
    </div>
  </div>

  <script>
    const amountInput = document.getElementById('amount');
    const categorySelect = document.getElementById('category');
    const dateInput = document.getElementById('date');
    const noteTextarea = document.getElementById('note');
    const addExpenseButton = document.getElementById('add-expense');
    const formErrorDiv = document.getElementById('form-error');
    const expenseList = document.querySelector('#list ul');
    const totalSpan = document.getElementById('total');
    const filterCategorySelect = document.getElementById('filter-category');
    const filterFromInput = document.getElementById('filter-from');
    const filterToInput = document.getElementById('filter-to');

    let expenses = JSON.parse(localStorage.getItem('expenses') || '[]');

    function updateUI() {
      expenseList.innerHTML = '';
      let visibleExpenses = expenses;

      if (filterCategorySelect.value !== 'all') {
        const category = filterCategorySelect.value;
        visibleExpenses = expenses.filter(expense => expense.category === category);
      }

      if (filterFromInput.value && filterToInput.value) {
        const fromDate = new Date(filterFromInput.value);
        const toDate = new Date(filterToInput.value);
        visibleExpenses = visibleExpenses.filter(expense =>
          new Date(expense.date) >= fromDate && new Date(expense.date) <= toDate
        );
      }

      visibleExpenses.forEach(expense => {
        const listItem = document.createElement('li');
        listItem.classList.add('expense');
        listItem.innerHTML = `
          ${expense.amount}: ${expense.category} - ${expense.date} 
          <button class="exp-del" data-id="${expense.id}">Delete</button>
        `;
        expenseList.appendChild(listItem);
      });

      totalSpan.textContent = visibleExpenses.reduce((sum, expense) => sum + expense.amount, 0).toFixed(2);

      visibleExpenses.forEach(expense => {
          const catDiv = document.querySelector(`[data-cat="${expense.category}"]`);
          if (catDiv) {
              catDiv.textContent = `${catDiv.textContent} ${visibleExpenses.filter(e => e.category === expense.category).reduce((sum, e) => sum + e.amount, 0).toFixed(2)}`;
          }
      });
    }

    function addExpense() {
      const amount = parseFloat(amountInput.value);
      const category = categorySelect.value;
      const date = dateInput.value;
      const note = noteTextarea.value || '';

      if (isNaN(amount) || amount <= 0 || !date) {
        formErrorDiv.textContent = 'Please enter a valid amount and date.';
        return;
      }

      const newExpense = { id: Date.now(), amount, category, date, note };
      expenses.push(newExpense);
      localStorage.setItem('expenses', JSON.stringify(expenses));
      updateUI();
      amountInput.value = '';
      categorySelect.value = 'groceries'; // Reset dropdown
      dateInput.value = '';
      noteTextarea.value = '';
      formErrorDiv.textContent = '';
    }

    function deleteExpense(event) {
        const button = event.target;
        const expenseId = button.dataset.id;
        const index = expenses.findIndex(expense => expense.id === parseInt(expenseId));
        if (index !== -1) {
            expenses.splice(index, 1);
            localStorage.setItem('expenses', JSON.stringify(expenses));
            updateUI();
        }
    }

    addExpenseButton.addEventListener('click', addExpense);
    expenseList.addEventListener('click', (event) => {
      if (event.target.classList.contains('exp-del')) {
        deleteExpense(event);
      }
    });

    // Initial load and periodic persistence
    updateUI();
    setInterval(() => {
       localStorage.setItem('expenses', JSON.stringify(expenses));
    }, 60000) // save every minute
  </script>

</body>
</html>
